$filePath = "X:\code\copilot-worktrees\P04\cirvine-msft-sturdy-adventure\assets\config.txt"

# Read the file
$bytes = [System.IO.File]::ReadAllBytes($filePath)
$text = [System.Text.Encoding]::UTF8.GetString($bytes)
$lines = $text -split "`n"

# Remove last empty element from final newline
if ($lines[-1] -eq "") {
    $lines = $lines[0..($lines.Length - 2)]
}

Write-Host "=== FINAL VERIFICATION ==="
Write-Host ""
Write-Host "Line Count: $($lines.Count) (expected: 12) - $(if($lines.Count -eq 12) {'✓'} else {'✗'})"
Write-Host ""

# Allowed characters set
$allowedChars = @("A".."Z") + @("0".."9") + @(" ", "+", "|", "/", "\", "_", "*", ".", "#", "(", ")", ":", "=", "-")
$allowedSet = [System.Collections.Generic.HashSet[char]]($allowedChars)

# Check each line
$allValid = $true
for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    $len = $line.Length
    $lenOk = ($len -ge 20 -and $len -le 48)

    # Check trailing whitespace
    $trailingWS = $line -match '\s$'

    # Check allowed chars
    $invalidChar = $null
    foreach ($char in $line.ToCharArray()) {
        if (-not $allowedSet.Contains($char)) {
            $invalidChar = $char
            break
        }
    }
    $charsOk = ($invalidChar -eq $null)

    $status = if ($lenOk -and -not $trailingWS -and $charsOk) { "✓" } else { "✗" }
    Write-Host "Line $($i+1): $len chars $status"

    if (-not $lenOk) {
        Write-Host "    - Length $len not in range [20,48]"
        $allValid = $false
    }
    if ($trailingWS) {
        Write-Host "    - Has trailing whitespace"
        $allValid = $false
    }
    if (-not $charsOk) {
        Write-Host "    - Invalid char: '$invalidChar'"
        $allValid = $false
    }
}

Write-Host ""
Write-Host "=== GLOBAL CHECKS ==="
$hasConfig = $text -match 'CONFIG'
Write-Host "Contains 'CONFIG': $(if($hasConfig) {'✓'} else {'✗'})"

$hasLowercase = $text -match '[a-z]'
Write-Host "No lowercase: $(if(-not $hasLowercase) {'✓'} else {'✗'})"

$endsWithNewline = ($bytes[-1] -eq 0x0A)
$noBOM = $bytes[0] -ne 0xEF
$singleNewlineEnd = if ($bytes.Count -ge 2) { $bytes[-2] -ne 0x0A } else { $false }
Write-Host "Ends with single newline: $(if($endsWithNewline -and $singleNewlineEnd) {'✓'} else {'✗'})"
Write-Host "No BOM: $(if($noBOM) {'✓'} else {'✗'})"

Write-Host ""
if ($allValid -and $hasConfig -and -not $hasLowercase -and $endsWithNewline -and $noBOM -and $singleNewlineEnd) {
    Write-Host "✅✅✅ ALL CONSTRAINTS SATISFIED ✅✅✅"
} else {
    Write-Host "❌ CONSTRAINTS NOT MET"
}

