$filePath = "X:\code\copilot-worktrees\P04\cirvine-msft-sturdy-adventure\assets\config.txt"
$bytes = [System.IO.File]::ReadAllBytes($filePath)
$text = [System.Text.Encoding]::UTF8.GetString($bytes)

# Proper test: Count matches
$lowerMatches = [regex]::Matches($text, '[a-z]')
$hasLowercase = $lowerMatches.Count -gt 0

Write-Host "Lowercase letters found: $hasLowercase (count: $($lowerMatches.Count))"

# Check all constraints properly
$lines = $text -split "`n"
if ($lines[-1] -eq "") {
    $lines = $lines[0..($lines.Length - 2)]
}

$allGood = $true

# 1. Exactly 12 lines
$check1 = $lines.Count -eq 12
Write-Host "✓ Exactly 12 lines: $check1"
if (-not $check1) { $allGood = $false }

# 2-4. Each line checks
$allowedChars = @("A".."Z") + @("0".."9") + @(" ", "+", "|", "/", "\", "_", "*", ".", "#", "(", ")", ":", "=", "-")
$allowedSet = [System.Collections.Generic.HashSet[char]]($allowedChars)
$check2and3and4 = $true

foreach ($i in 0..($lines.Count-1)) {
    $line = $lines[$i]
    $len = $line.Length

    # Length 20-48
    if ($len -lt 20 -or $len -gt 48) {
        Write-Host "✗ Line $($i+1): length $len out of range [20,48]"
        $check2and3and4 = $false
    }

    # No trailing whitespace
    if ($line -match '\s$') {
        Write-Host "✗ Line $($i+1): has trailing whitespace"
        $check2and3and4 = $false
    }

    # Only allowed characters
    foreach ($char in $line.ToCharArray()) {
        if (-not $allowedSet.Contains($char)) {
            Write-Host "✗ Line $($i+1): contains invalid char '$char'"
            $check2and3and4 = $false
        }
    }
}
if ($check2and3and4) { Write-Host "✓ All lines 20-48 chars, no trailing WS, only allowed chars" }
if (-not $check2and3and4) { $allGood = $false }

# 5. Contains CONFIG
$check5 = $text -match 'CONFIG'
Write-Host "✓ Contains CONFIG: $check5"
if (-not $check5) { $allGood = $false }

# 6. No lowercase
$check6 = -not $hasLowercase
Write-Host "✓ No lowercase letters: $check6"
if (-not $check6) { $allGood = $false }

# 7. Ends with exactly one newline
$check7 = ($bytes[-1] -eq 0x0A) -and ($bytes[-2] -ne 0x0A)
Write-Host "✓ Ends with exactly one newline: $check7"
if (-not $check7) { $allGood = $false }

# 8. ASCII only
$check8 = $bytes | Where-Object { $_ -gt 127 } | Measure-Object | Select-Object -ExpandProperty Count
$check8ok = $check8 -eq 0
Write-Host "✓ ASCII only: $check8ok"
if (-not $check8ok) { $allGood = $false }

Write-Host ""
if ($allGood) {
    Write-Host "✅✅✅ ALL CONSTRAINTS SATISFIED ✅✅✅"
} else {
    Write-Host "❌ Some constraints failed"
}

